{
  "claims": [
    {
      "claim": "Renaming identifiers in TLA+ specifications reduces the correctness scores of LLM-generated specifications.",
      "evidence": "renaming lowers the correctness of Claude Opus 4.8 from 28% to 18% and of GPT-5 from 9% to 7%."
    },
    {
      "claim": "The decrease in correctness scores is largely due to the test grading requiring exact names that are often not stated in the descriptions.",
      "evidence": "Most of this decrease comes from how the test grades, which requires exact names that most descriptions never state."
    },
    {
      "claim": "Grading by behavior instead of exact names reduces the impact of renaming on correctness scores.",
      "evidence": "Grading by behavior shrinks the decrease to about 3 percentage points for Opus 4.8 and to 0 for GPT-5."
    },
    {
      "claim": "Renaming identifiers in fine-tuned models reduces the training gain in likelihood and affects performance on unseen tasks.",
      "evidence": "In two model families fine-tuned on disjoint halves of the tasks, renaming removes about half of the training gain in likelihood and costs 4.9 percentage points (Qwen) and 1.3 percentage points (Gemma) on unseen tasks."
